    ('5856550e-cdff-5a40-928a-7841fd40f246'::uuid, '32d0cc50-ac5d-57f8-9f4c-6b0a73f01e3e'::uuid, 'Que signifie le mot « martyr » ?', 'mcq', '["Témoin","Victime","Prêtre","Croyant"]'::jsonb, 0, 'Ils sont vénérés par les communautés.', 3),
