    ('ffc954d8-2a09-53ca-9d86-10a442f75c54'::uuid, '32d0cc50-ac5d-57f8-9f4c-6b0a73f01e3e'::uuid, 'Que fait l’édit de Thessalonique en 380 ?', 'mcq', '["Il fait du christianisme la religion officielle de l’Empire","Il autorise tous les cultes","Il persécute les chrétiens","Il divise l’Empire"]'::jsonb, 0, 'Théodose en est l’auteur.', 5),
