    ('05f02748-db13-572f-b522-2515c1b5a3fe'::uuid, '2c158090-a618-5691-bba8-3c676cb5c1b4'::uuid, 'Dans les métropoles à croissance rapide, les équipements suivent le rythme de la population.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est précisément ce décalage qui produit les bidonvilles.', 8),
    ('6dc5bd7e-0807-5e93-a628-4a252220e51b'::uuid, '3937868b-1d6b-52a9-b9fd-b7a302657b5f'::uuid, 'Quelle part de l’humanité vivra en ville en 2050 ?', 'mcq', '["Environ 7 sur 10","Environ 3 sur 10","Environ 5 sur 10","La totalité"]'::jsonb, 0, 'La proportion est d’environ 60 % aujourd’hui.', 1),
    ('b1bae497-f4cd-52cd-ae6d-df8578c3955c'::uuid, '3937868b-1d6b-52a9-b9fd-b7a302657b5f'::uuid, 'Quelles sont les trois exigences de la ville durable ?', 'mcq', '["Environnementale, sociale et économique","Politique, militaire et religieuse","Esthétique, historique et touristique","Technique, numérique et financière"]'::jsonb, 0, 'Elles doivent être conciliées.', 2),
    ('ab7bb1b5-e4ea-52ad-ab33-76c4bd3fe149'::uuid, '3937868b-1d6b-52a9-b9fd-b7a302657b5f'::uuid, 'Pourquoi densifier plutôt que s’étaler ?', 'mcq', '["Pour préserver les terres agricoles et naturelles","Pour construire moins cher","Pour augmenter la circulation","Pour réduire le nombre d’habitants"]'::jsonb, 0, 'L’étalement urbain consomme les espaces naturels.', 3),
