    ('c2e35bcf-ce9d-542e-9de8-77979b7f8cde'::uuid, '3937868b-1d6b-52a9-b9fd-b7a302657b5f'::uuid, 'Qu’est-ce qu’un écoquartier ?', 'mcq', '["Un quartier conçu selon les principes du développement durable","Un quartier réservé aux espaces verts","Un quartier sans habitants","Un quartier industriel"]'::jsonb, 0, 'Vauban à Fribourg et Hammarby à Stockholm en sont.', 5),
    ('4e3ccb40-7382-5889-bd4c-2fe61ba49eff'::uuid, '3937868b-1d6b-52a9-b9fd-b7a302657b5f'::uuid, 'Quel intérêt présente la réhabilitation des friches industrielles ?', 'mcq', '["Elle évite de construire sur des terrains neufs","Elle coûte toujours moins cher","Elle augmente l’étalement urbain","Elle supprime les transports"]'::jsonb, 0, 'On réutilise un espace déjà artificialisé.', 6),
