    ('ba16ba2f-642d-5d97-9ab7-0881edd1fc54'::uuid, '3937868b-1d6b-52a9-b9fd-b7a302657b5f'::uuid, 'Une ville devient durable dès qu’elle installe des capteurs numériques.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La technique ne suffit pas : ce sont les conditions de vie qui comptent.', 8),
    ('16043a53-a33f-552a-a92d-72b72aadcd1b'::uuid, '85c5f32d-7600-51dc-a956-0ecdc2814afd'::uuid, 'Comment calcule-t-on la densité de population ?', 'mcq', '["Nombre d’habitants ÷ superficie en km²","Nombre d’habitants × superficie","Superficie ÷ nombre d’habitants","Nombre de logements par habitant"]'::jsonb, 0, 'Elle s’exprime en hab./km².', 1),
    ('028109f9-f365-5fb8-b682-b0f5ff3a8ee7'::uuid, '85c5f32d-7600-51dc-a956-0ecdc2814afd'::uuid, 'Qu’est-ce que le permafrost ?', 'mcq', '["Un sol gelé en permanence","Un vent polaire","Une culture de l’Arctique","Un type d’habitat"]'::jsonb, 0, 'Sa fonte est un effet du changement climatique.', 2),
