    ('0807a89f-3c1d-544c-9fab-fda4c9347af7'::uuid, '85c5f32d-7600-51dc-a956-0ecdc2814afd'::uuid, 'Quel peuple pratique le nomadisme pastoral au Sahara ?', 'mcq', '["Les Touaregs","Les Sames","Les Inuits","Les Mongols"]'::jsonb, 0, 'Les Sames sont en Laponie, les Mongols en Asie centrale.', 5),
    ('1906ff1f-d8f8-5261-9bda-400f9513955d'::uuid, '85c5f32d-7600-51dc-a956-0ecdc2814afd'::uuid, 'Quelle contrainte caractérise l’Amazonie et le bassin du Congo ?', 'mcq', '["La forêt dense, difficile d’accès, aux sols pauvres","Le froid extrême","La sécheresse","L’altitude"]'::jsonb, 0, 'Malgré l’abondance végétale, les sols y sont pauvres.', 6),
