    ('a3abccd1-7b71-5a4d-8bc9-24b13fb4c223'::uuid, '1617b2cf-55bc-5495-b2d8-c4d334b72b68'::uuid, 'Que signifie qu’une espèce est « endémique » ?', 'mcq', '["Elle ne vit nulle part ailleurs","Elle est menacée","Elle est très nombreuse","Elle a été introduite"]'::jsonb, 0, '80 % des espèces de Madagascar le sont.', 2),
    ('30c24a75-77ea-593a-84af-6b317769c8b5'::uuid, '1617b2cf-55bc-5495-b2d8-c4d334b72b68'::uuid, 'Quelle part des espèces connues l’Amazonie abrite-t-elle ?', 'mcq', '["Environ 10 %","Environ 50 %","Environ 1 %","Environ 80 %"]'::jsonb, 0, 'C’est un haut lieu de la biodiversité mondiale.', 3),
    ('5de7fcf3-faa6-541a-817f-3df5a5e83d4d'::uuid, '1617b2cf-55bc-5495-b2d8-c4d334b72b68'::uuid, 'Quelle est la principale cause de la déforestation tropicale ?', 'mcq', '["L’agriculture industrielle et l’élevage","Le tourisme","Les peuples autochtones","Les parcs nationaux"]'::jsonb, 0, 'Soja, huile de palme et exploitation du bois.', 4),
    ('1b223344-a4b5-5564-8deb-65a944dd2217'::uuid, '1617b2cf-55bc-5495-b2d8-c4d334b72b68'::uuid, 'Quelle menace pèse sur les récifs coralliens ?', 'mcq', '["Le réchauffement, qui provoque leur blanchiment","Le froid","La déforestation","L’orpaillage seul"]'::jsonb, 0, 'La Grande Barrière en souffre fortement.', 5),
    ('f5a99278-9ade-5d18-a87b-72077b5a9816'::uuid, '1617b2cf-55bc-5495-b2d8-c4d334b72b68'::uuid, 'Qu’est-ce que l’écotourisme ?', 'mcq', '["Un tourisme à faible impact qui finance la protection du milieu","Un tourisme de masse","Un tourisme interdit aux étrangers","La visite de parcs urbains"]'::jsonb, 0, 'Il fait du milieu une ressource économique.', 6),
