    ('847b39b4-2d1f-519d-9f7e-442cd705cff7'::uuid, '1617b2cf-55bc-5495-b2d8-c4d334b72b68'::uuid, 'Les espaces de grande biodiversité sont des espaces vierges de toute présence humaine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils sont peuplés depuis des millénaires.', 8),
    ('1366559a-61e3-513b-8447-0e385130268c'::uuid, '93b8a23b-7db8-5ffe-a518-4c6f0f271e1a'::uuid, 'Quelle part des actifs les agriculteurs représentent-ils en France aujourd’hui ?', 'mcq', '["Moins de 2 %","Environ 10 %","Environ 30 %","Environ 20 %"]'::jsonb, 0, 'Ils étaient plus de 30 % en 1950.', 1),
